giffler_thompson <- function(instance, rule, positions = NULL) {
    starts <- integer(length(instance$operations))
    next_index <- rep(1L, 13L)
    ready <- integer(13L)
    free <- integer(instance$machine_count)
    decisions <- ties <- 0L
    for (step in seq_along(starts)) {
        candidates <- list()
        for (job in instance$jobs) if (next_index[job$number] <= length(job$operations)) {
            id <- job$operations[next_index[job$number]]
            op <- instance$operations[[id]]
            candidates <- c(candidates, list(list(id = id, start = max(ready[op$job], free[op$machine]))))
        }
        cutoff <- min(vapply(
            candidates,
            function(item) item$start + instance$operations[[item$id]]$duration,
            0L
        ))
        selected <- Filter(
            function(item) item$start + instance$operations[[item$id]]$duration == cutoff,
            candidates
        )
        machine <- min(vapply(selected, function(item) instance$operations[[item$id]]$machine, 0L))
        conflict <- Filter(
            function(item) instance$operations[[item$id]]$machine == machine && item$start < cutoff,
            candidates
        )
        priority <- function(item) {
            op <- instance$operations[[item$id]]
            switch(
                rule,
                SPT = op$duration,
                LPT = -op$duration,
                MWKR = -op$duration - op$tail,
                FIFO = ready[op$job],
                GENES = positions[item$id]
            )
        }
        values <- vapply(conflict, priority, 0L)
        lowest <- min(values)
        decisions <- decisions + as.integer(length(conflict) > 1L)
        ties <- ties + as.integer(sum(values == lowest) > 1L)
        item <- conflict[[which.min(values)]]
        op <- instance$operations[[item$id]]
        starts[item$id] <- item$start
        ready[op$job] <- free[machine] <- item$start + op$duration
        next_index[op$job] <- next_index[op$job] + 1L
    }
    list(starts = starts, decisions = decisions, ties = ties)
}

chart_scale <- function(makespan, width) {
    magnitude <- 1L
    repeat {
        for (step in c(1L, 2L, 5L)) {
            scale <- step * magnitude
            columns <- (makespan + scale - 1L) %/% scale
            if (columns <= width) return(c(scale, columns))
        }
        magnitude <- magnitude * 10L
    }
}
time_row <- function(scale, columns) {
    row <- "time"
    for (column in seq.int(0L, columns - 1L, 10L)) row <- paste0(
        row,
        strrep(" ", max(0L, 6L + column - nchar(row))),
        column * scale
    )
    row
}
rule_row <- function(columns) paste0(
    "      ",
    paste(ifelse(seq.int(0L, columns - 1L) %% 10L == 0L, "+", "-"), collapse = "")
)
framed <- function(label, marks) paste0(sprintf("%-4s", label), " |", marks, "|")
chart_row <- function(label, intervals, scale, columns) {
    intervals <- intervals[order(vapply(intervals, function(item) item$start, 0L))]
    marks <- vapply(seq.int(0L, columns - 1L), function(column) {
        mark <- "."
        widest <- 0L
        for (item in intervals) {
            overlap <- min(item$end, (column + 1L) * scale) - max(item$start, column * scale)
            if (overlap > widest) {
                mark <- item$symbol
                widest <- overlap
            }
        }
        mark
    }, "")
    framed(label, paste(marks, collapse = ""))
}
busy_row <- function(intervals, scale, columns) {
    marks <- vapply(seq.int(0L, columns - 1L), function(column) {
        time <- column * scale
        busy <- sum(vapply(
            intervals,
            function(row) any(vapply(row, function(item) item$start <= time && time < item$end, FALSE)),
            FALSE
        ))
        if (busy == 10L) "X" else as.character(busy)
    }, "")
    framed("busy", paste(marks, collapse = ""))
}

gene_operations <- function(instance, chromosome) {
    counts <- integer(13L)
    ids <- integer()
    for (gene in chromosome) {
        counts[gene] <- counts[gene] + 1L
        ids <- c(ids, instance$job_map[[as.character(gene)]]$operations[counts[gene]])
    }
    ids
}
decode <- function(instance, chromosome) {
    starts <- integer(length(instance$operations))
    ready <- integer(13L)
    free <- integer(instance$machine_count)
    for (id in gene_operations(instance, chromosome)) {
        op <- instance$operations[[id]]
        starts[id] <- max(ready[op$job], free[op$machine])
        ready[op$job] <- free[op$machine] <- starts[id] + op$duration
    }
    starts
}
tournament <- function(rng, values, size) {
    picks <- vapply(seq_len(size), function(i) below(rng, length(values)) + 1L, 0L)
    picks[order(values[picks], picks)[1L]]
}
crossover <- function(rng, first, second, jobs) {
    kept <- jobs[vapply(jobs, function(job) below(rng, 2L) == 0L, FALSE)]
    preserve <- function(keeper, donor) {
        fillers <- donor[!(donor %in% kept)]
        keeper[!(keeper %in% kept)] <- fillers
        keeper
    }
    list(preserve(first, second), preserve(second, first))
}
swap_mutation <- function(rng, chromosome) {
    a <- below(rng, length(chromosome)) + 1L
    b <- below(rng, length(chromosome)) + 1L
    chromosome[c(a, b)] <- chromosome[c(b, a)]
    chromosome
}
insert_mutation <- function(rng, chromosome) {
    a <- below(rng, length(chromosome)) + 1L
    b <- below(rng, length(chromosome)) + 1L
    gene <- chromosome[a]
    chromosome <- chromosome[-a]
    append(chromosome, gene, after = b - 1L)
}

minstd <- function(seed) {
    rng <- new.env(parent = emptyenv())
    rng$state <- seed
    rng
}
draw <- function(rng) {
    value <- 48271L * (rng$state %% 44488L) - 3399L * (rng$state %/% 44488L)
    if (value <= 0L) value <- value + 2147483647L
    rng$state <- value
    value
}
below <- function(rng, limit) draw(rng) %% limit
chance <- function(rng, fraction) below(rng, fraction[2L]) < fraction[1L]
shuffle_genes <- function(rng, genes) {
    if (length(genes) > 1L) for (i in seq.int(length(genes), 2L)) {
        j <- below(rng, i) + 1L
        genes[c(i, j)] <- genes[c(j, i)]
    }
    genes
}
